/**
 * A string drawn as a scannable QR Code symbol (`design/components/qr-code.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/qr-code.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  QR_QUIET_ZONE,
  derived,
  devWarning,
  qrPath,
  qrSymbol,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/qr-code.module.css'

export type QRCodeSize = NonNullable<QRCodeProps['size']>

export type QRCodeErrorCorrection = NonNullable<QRCodeProps['errorCorrection']>

/** A string drawn as a scannable QR Code symbol: the inputs it takes, by the React member's prop names. */
export interface QRCodeProps {
  /**
   * Damage tolerance: `L` 7%, `M` 15%, `Q` 25%, `H` 30%. More correction means a denser symbol,
   * the worse trade on a screen: displays do not get scuffed, and dense symbols scan worse at
   * arm's length. `M` is the screen default.
   */
  errorCorrection?: 'L' | 'M' | 'Q' | 'H'
  /**
   * The accessible name: what the symbol is *for* ("Authenticator setup code"), never its
   * contents. Required, because the symbol is noise to a reader who cannot scan it.
   */
  label: string
  size?: 'sm' | 'md' | 'lg'
  /**
   * The content, encoded as UTF-8; always controlled, as the symbol is a pure function of it.
   */
  value: string
}

/** A string drawn as a scannable QR Code symbol. */
@Component({
  selector: 'pm-qr-code',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `@if (e1()) {<!-- symbol -->
<svg
[attr.class]="e2()"
[attr.viewBox]="e3()"
role="img"
[attr.aria-label]="e4()"
shape-rendering="crispEdges"
[attr.data-size]="e5()"
data-mode="light"
data-member="qr-code"
><!-- paper -->
<rect
[attr.class]="e6()"
[attr.width]="e7()"
[attr.height]="e7()"
></rect>
<!-- ink -->
<path
[attr.class]="e8()"
[attr.d]="e9()"
></path></svg>}`,
})
export class QRCode {
  /**
   * Damage tolerance: `L` 7%, `M` 15%, `Q` 25%, `H` 30%. More correction means a denser symbol,
   * the worse trade on a screen: displays do not get scuffed, and dense symbols scan worse at
   * arm's length. `M` is the screen default.
   */
  readonly errorCorrection = input<
    Exclude<QRCodeProps['errorCorrection'], undefined>,
    QRCodeProps['errorCorrection']
  >('M', {
    transform: (value: QRCodeProps['errorCorrection']) => (value === undefined ? 'M' : value),
  })
  /**
   * The accessible name: what the symbol is *for* ("Authenticator setup code"), never its
   * contents. Required, because the symbol is noise to a reader who cannot scan it.
   */
  readonly label = input.required<QRCodeProps['label']>()
  readonly size = input<Exclude<QRCodeProps['size'], undefined>, QRCodeProps['size']>('md', {
    transform: (value: QRCodeProps['size']) => (value === undefined ? 'md' : value),
  })
  /**
   * The content, encoded as UTF-8; always controlled, as the symbol is a pure function of it.
   */
  readonly value = input.required<QRCodeProps['value']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      errorCorrection: () => this.errorCorrection(),
      label: () => this.label(),
      size: () => this.size(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly symbol = derived(() => qrSymbol(this.$p.value, this.$p.errorCorrection))
  protected readonly extent = derived(() =>
    this.symbol.value === null ? 0 : this.symbol.value.size + QR_QUIET_ZONE * 2,
  )
  protected readonly ink = derived(() =>
    this.symbol.value === null ? '' : qrPath(this.symbol.value, QR_QUIET_ZONE),
  )

  constructor() {
    watchEffect(
      () => [this.symbol.value, this.$p.errorCorrection],
      () => this.effect1(),
      true,
    )
    watchEffect(
      () => this.$p.value,
      () => this.effect2(),
      true,
    )
  }

  protected e1() {
    return this.symbol.value !== null && this.$p.value !== ''
  }

  protected e2() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return styles.symbol
  }

  protected e3() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return `0 0 ${this.extent.value} ${this.extent.value}`
  }

  protected e4() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return this.$p.label
  }

  protected e5() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return this.$p.size
  }

  protected e6() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return styles.paper
  }

  protected e7() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return this.extent.value
  }

  protected e8() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return styles.ink
  }

  protected e9() {
    if (!(this.symbol.value !== null && this.$p.value !== '')) return undefined as never
    return this.ink.value
  }

  private effect1(): void {
    devWarning(
      this.symbol.value === null,
      `QRCode: \`value\` (${this.$p.value.length} characters) does not fit a QR symbol at correction level ${this.$p.errorCorrection}. Nothing was rendered.`,
    )
  }

  private effect2(): void {
    devWarning(this.$p.value === '', 'QRCode: `value` is empty. Nothing was rendered.')
  }
}
